from app.db import store


def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)


def name_stats() -> dict:
    """Return count, min, max and average length of all user names."""
    lengths = [len(user["name"]) for user in store.list_all()]
    return {
        "count": len(lengths),
        "min": min(lengths),
        "max": max(lengths),
        "average": round(sum(lengths) / len(lengths), 2),
    }
